-- =====================================================================
-- Startversie van je vragenlijst (inclusief "Je merkgevoel", "Je logo" en "Je templates").
-- Draai dit NA 01-schema.sql. Daarna pas je de vragenlijst aan in je keuken.
-- Delen met "voorwaarde" (logo, templates) ziet een klant alleen als het in haar pakket zit.
-- =====================================================================
insert into public.portal_settings (id) values (1) on conflict (id) do nothing;
update public.portal_settings set vragenlijst = $vl$[{"id":"jij","titel":"Jij","intro":"Je quiz zegt {archetype}. Nu wil ik weten wie erachter zit.","vragen":[{"id":"verhaal","l":"Hoe ben je hier gekomen? Vertel het zoals je het zou vertellen aan iemand die je vertrouwt: een vriend(in), je partner of een collega.","t":"area","vb":"Bijv. ik werkte tien jaar in de zorg tot ik merkte dat..."},{"id":"trots","l":"Waar ben je stiekem het meest trots op in je werk?","t":"area"},{"id":"rafels","l":"Welke rafelrandjes horen bij jou, maar laat je nu nog weg?","t":"area","vb":"Bijv. ik ben chaotisch, ik huil makkelijk, ik ben geen ochtendmens"}]},{"id":"business","titel":"Je business","intro":"Waar staat je keuken nu?","vragen":[{"id":"wat","l":"Wat doe je, in één of twee zinnen?","t":"area","vb":"Zoals je het nu zou zeggen, ook als het nog niet lekker loopt"},{"id":"vakgebied","l":"In welk vakgebied werk je?","t":"text","vb":"Bijv. burn-outpreventie, loopbaancoaching, financieel advies","tool":"vakgebied"},{"id":"klantwoord","l":"Hoe noem jij de mensen met wie je werkt?","t":"text","vb":"Bijv. klanten, cliënten, deelnemers, founders","tool":"klantwoord"},{"id":"aanbodwoord","l":"Hoe noem jij wat je aanbiedt?","t":"text","vb":"Bijv. traject, programma, sessies, opdracht","tool":"aanbodwoord"},{"id":"sinds","l":"Hoe lang ben je ondernemer?","t":"keuze","opties":["Korter dan 1 jaar","1 tot 3 jaar","3 tot 5 jaar","Langer dan 5 jaar"]},{"id":"platformen","l":"Op welke kanalen ben je actief, of wil je actief worden?","t":"meerkeuze","opties":["Instagram","LinkedIn","Facebook","TikTok","YouTube","Pinterest","E-mail en nieuwsbrief"],"tool":"platformen"},{"id":"kanaal","l":"Waar komen je klanten nu vooral vandaan?","t":"keuze","opties":["Instagram","LinkedIn","Netwerk en mond-tot-mond","Website en Google","Nog geen vast kanaal"]},{"id":"capaciteit","l":"Hoeveel klanten wil je tegelijk begeleiden?","t":"text"}]},{"id":"klant","titel":"Je klant","intro":"Voor wie kook je eigenlijk?","vragen":[{"id":"doelgroep","l":"Voor wie werk je het allerliefst? Eén zin.","t":"text","vb":"Bijv. coaches die klaar zijn met gratis advies geven","tool":"doelgroep"},{"id":"pijn","l":"Waar lopen je klanten tegenaan als ze bij jou aankloppen?","t":"area","tool":"pijn"},{"id":"resultaat","l":"Wat is er voor hen anders als jullie samen klaar zijn?","t":"area","tool":"resultaat"}]},{"id":"stem","titel":"Je stem","intro":"Als {archetype} klink je waarschijnlijk {woorden}. Klopt dat?","vragen":[{"id":"toon","l":"Drie woorden: zo wil je klinken","t":"text","vb":"Bijv. {woorden}","tool":"toon"},{"id":"nooit","l":"Zo wil je nóóit klinken","t":"text","vb":"Bijv. zweverig, schreeuwerig, belerend","tool":"nooit"},{"id":"bewonder","l":"Welke merken of mensen raken jou, en waarom?","t":"area"}]},{"id":"merkgevoel","titel":"Je merkgevoel","intro":"Hoe moet jouw merk voelen, en wat mag blijven?","vragen":[{"id":"gevoel","l":"Welk gevoel wil je dat mensen krijgen als ze met jou en je merk in aanraking komen?","t":"area","vb":"Bijv. rust, vertrouwen, \"eindelijk iemand die me snapt\"","tool":"gevoel"},{"id":"kleuren","l":"Wat zijn je lievelingskleuren, of welke kleuren gebruik je nu in je branding?","t":"text","vb":"Bijv. diep groen, zand en goud","tool":"kleurwens"},{"id":"behouden","l":"Wat doe je nu al in je branding dat je graag wilt houden? (optioneel)","t":"area","vb":"Bijv. mijn logo, mijn foto's, de manier waarop ik mijn posts afsluit","tool":"behouden"}]},{"id":"logo","titel":"Je logo","voorwaarde":"logo","intro":"Zodat ik weet waar we starten.","vragen":[{"id":"logo","l":"Heb je al een logo?","t":"keuze","opties":["Ja, en die wil ik houden","Ja, maar ik wil een nieuw logo","Nee, nog niet"]},{"id":"logovoorbeelden","l":"Wil je een nieuw logo? Geef voorbeelden of links van logo's die je mooi vindt, en waarom. Heb je al een logo? Lever het aan bij de eerste gang.","t":"area","vb":"Bijv. een link naar een Pinterest-bord, of: strak en rustig, zoals…"}]},{"id":"templatewensen","titel":"Je templates","voorwaarde":"templates","intro":"Zodat je templates precies doen wat jij nodig hebt.","vragen":[{"id":"tdoel","l":"Waar moeten je templates je vooral bij helpen?","t":"meerkeuze","opties":["Zichtbaarheid en opbouw","Een lancering","Verkopen","Autoriteit en vertrouwen"]},{"id":"tformats","l":"Welke formats gebruik je (of wil je gaan gebruiken)?","t":"meerkeuze","opties":["Instagram posts","Carrousels","Stories","Reels-covers","LinkedIn posts","Pinterest pins","Nieuwsbrief"]},{"id":"tsoort","l":"Wat voor content post je het meest?","t":"area","vb":"Bijv. tips, klantverhalen, achter de schermen, aanbod"},{"id":"tvoorbeeld","l":"Welke accounts of templates vind je mooi, en waarom?","t":"area","vb":"Links of namen, en wat je er zo goed aan vindt"},{"id":"tlastig","l":"Wat vind je nu het lastigst aan je content maken?","t":"area"},{"id":"tplanning","l":"Staat er binnenkort iets op de planning, zoals een lancering?","t":"text","vb":"Bijv. in maart lanceer ik mijn groepsprogramma"}]},{"id":"aanbod","titel":"Je aanbod","intro":"Wat staat er nu op je kaart?","vragen":[{"id":"aanbod","l":"Wat bied je nu aan, en voor welke prijs?","t":"area"},{"id":"meer","l":"Wat wil je méér verkopen?","t":"text"}]},{"id":"wensen","titel":"Je wensen","intro":"Zodat ik precies weet waar we naartoe werken.","vragen":[{"id":"succes","l":"Wanneer is dit traject voor jou een succes?","t":"area"},{"id":"spannend","l":"Wat vind je spannend aan dit traject?","t":"area"},{"id":"samenwerken","l":"Hoe wil je dat ik met je werk?","t":"text","vb":"Bijv. direct maar warm, veel sparren"}]},{"id":"praktisch","titel":"Praktisch","intro":"Laatste stap, {voornaam}. Dan kan het feest beginnen.","vragen":[{"id":"instagram","l":"Instagram","t":"text","vb":"@jouwnaam"},{"id":"website","l":"Website","t":"text"},{"id":"shoot","l":"Ideeën of plekken voor je brand shoot?","t":"area"}]}]$vl$::jsonb where id = 1;
